from mazegenerator import MazeGenerator
import pygame
from pygame.locals import (
    K_UP,
    K_DOWN,
    K_LEFT,
    K_RIGHT,
    K_ESCAPE,
    KEYDOWN,
    QUIT,
)
from .pm_config import PmConfig

# • A maze with walls and corridors, generated by the assigned A-Maze-ing package.
# • The first level is composed of a maze generated with a fixed seed (e.g., 42), then, each
# subsequent level is composed of a maze randomly generated.
# • Pacgums (small dots) in most corridors.
# • Super-pacgums (power pellets) in the 4 corners of the maze.
# • 4 ghosts, one in each corner of the maze.
# • The player starts in the middle of the maze


# class Level:
#     def __init__(self):
#         pass


N, E, S, W = 1, 2, 4, 8
Margin = 40
WallColor = (60, 90, 200)

gen = MazeGenerator(size=(15, 15), perfect=False, seed=42)
grid = gen.maze
height, width = len(grid), len(grid[0])

def draw_line(screen: pygame.Surface, start: tuple[int, int], end: tuple[int, int], color: tuple[int, int, int], width: int = 1) -> None:
    pygame.draw.line(screen, color, start, end, width)

def draw_rectangle(screen: pygame.Surface, rect: pygame.Rect, color: tuple[int, int, int], width: int = 0) -> None:
    pygame.draw.rect(screen, color, rect, width)

def draw_maze(screen: pygame.Surface, grid: list[list[int]], cell_size: int = 40) -> None:
    for y, row in enumerate(grid):
        for x, cell in enumerate(row):
            px = x * cell_size
            py = y * cell_size
            if cell == 15:  
                draw_rectangle(screen, pygame.Rect(px, py, cell_size, cell_size), (0, 0, 255))
            if cell & N:  
                draw_line(screen, (px, py), (px + cell_size, py), WallColor, 2)
            if cell & E:  
                draw_line(screen, (px + cell_size, py), (px + cell_size, py + cell_size), WallColor, 2)
            if cell & S:  
                draw_line(screen, (px, py + cell_size), (px + cell_size, py + cell_size), WallColor, 2)
            if cell & W:  
                draw_line(screen, (px, py), (px, py + cell_size), WallColor, 2)


screen = pygame.display.set_mode((width * 40, height * 40 + Margin))
pygame.init()
clock = pygame.time.Clock()
pygame.display.set_caption("Pac-Man")
run = True
while run:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            run = False
        elif event.type == KEYDOWN:
            # Was it the Escape key? If so, stop the loop.
            if event.key == K_ESCAPE:
                run = False

    screen.fill((0, 0, 0))
    draw_maze(screen, grid)
    pygame.display.flip()
    clock.tick(60)
pygame.quit()
 
    